import{_ as t,o as e,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/glossary.md","filePath":"en/guide/glossary.md"}'),r={name:"en/guide/glossary.md"};function s(d,a,o,l,c,h){return e(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>Status:</strong> Design vocabulary · Individual mechanics retain their stated status.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/en/guide/characters/skills.html">Skill</a>, <a href="/Syrolands-Public/en/guide/characters/techniques.html">Technique</a>, <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> and <a href="/Syrolands-Public/en/guide/glossary.html#mastery">Mastery</a> describe different kinds of progress.</li><li>Knowing an option, preparing it and successfully using it are separate steps.</li><li>Use these definitions while reading; consult the linked specs for detailed rules.</li></ul><h2 id="terms-at-a-glance" tabindex="-1">Terms at a glance <a class="header-anchor" href="#terms-at-a-glance" aria-label="Permalink to &quot;Terms at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><span id="skill"></span><a href="/Syrolands-Public/en/guide/characters/skills.html">Skill</a></td><td>Character capability in a broad activity; not the entire catalogue of learned options.</td></tr><tr><td><span id="technique"></span><a href="/Syrolands-Public/en/guide/characters/techniques.html">Technique</a></td><td>A learned option or method; having enough skill does not automatically teach every technique.</td></tr><tr><td><span id="familiarity"></span><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a></td><td>Practiced fluency with a particular action or pattern; distinct from learning it and from broad skill.</td></tr><tr><td><span id="mastery"></span>Mastery</td><td>Deeper expertise or specialization; not a synonym for a skill total or the Familiarity state named Mastered.</td></tr><tr><td><span id="special-attack"></span><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attack (SA)</a></td><td>A learned martial action with its own use, commitment and cost.</td></tr><tr><td><span id="legacy-combat"></span><a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Legacy Combat</a></td><td>Automatic attack cadence, retained as a supported design alternative.</td></tr><tr><td><span id="modern-combat"></span><a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modern Combat</a></td><td>The player chooses when to begin an available action; timing does not guarantee success.</td></tr><tr><td><span id="flow"></span><a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a></td><td>Sustainable combat rhythm shaped by action choice, exertion and recovery.</td></tr><tr><td><span id="core-pattern"></span><a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Core Pattern</a></td><td>The learned structure of a spell; variants can modify it without erasing its identity.</td></tr><tr><td><span id="active-memory"></span><a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Active Memory</a></td><td>The selection of learned spell patterns prepared for immediate access to normal casting, not instant casting.</td></tr><tr><td><span id="concentration"></span><a href="/Syrolands-Public/en/guide/magic/meditation-and-concentration.html">Concentration</a></td><td>Stability under pressure while casting or sustaining suitable mental work; not automatically another skillcap cost.</td></tr><tr><td><span id="local-trauma"></span><a href="/Syrolands-Public/en/guide/combat/limbs-and-trauma.html">Local Trauma</a></td><td>Structural harm to a body region, distinct from global health damage.</td></tr><tr><td><span id="global-hits"></span><a href="/Syrolands-Public/en/guide/combat/limbs-and-trauma.html">Global Hits</a></td><td>Overall health, which coexists with local body-region condition.</td></tr><tr><td><span id="masterwork"></span><a href="/Syrolands-Public/en/guide/items/item-quality.html">Masterwork</a></td><td>A rare craft achievement within the quality proposal; not automatically a magical item.</td></tr><tr><td><span id="latent-property"></span><a href="/Syrolands-Public/en/guide/items/item-quality.html">Latent Property</a></td><td>A possible hidden potential revealed through suitable use or discovery; not guaranteed on every good item.</td></tr><tr><td><span id="profession-path"></span><a href="/Syrolands-Public/en/guide/professions/overview.html">Profession Path</a></td><td>A specialization within a profession, expressed through knowledge and techniques rather than a mandatory separate skill.</td></tr><tr><td><span id="prepared-repertoire"></span><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Prepared Repertoire</a></td><td>The martial options selected for ready access; separate from magical Active Memory and not a mandatory INT investment.</td></tr><tr><td><span id="wind-up"></span>Wind-up</td><td>Preparation before an action can connect; starting an action does not produce an instant hit.</td></tr><tr><td><span id="active-window"></span>Active Window</td><td>The phase in which an action can connect, subject to its checks; not a promise of repeated hits.</td></tr><tr><td><span id="recovery"></span><a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Recovery</a></td><td>The remaining commitment after an action before another eligible action can begin; not the same as healing an injury.</td></tr><tr><td><span id="reach"></span><a href="/Syrolands-Public/en/guide/combat/reach-and-spacing.html">Reach</a></td><td>The maximum physical distance threatened by a particular action; skill does not invisibly extend it.</td></tr><tr><td><span id="effective-range"></span><a href="/Syrolands-Public/en/guide/combat/reach-and-spacing.html">Effective Range</a></td><td>The useful or preferred distance band for an action; being within maximum reach does not ensure ideal handling.</td></tr><tr><td><span id="telegraph"></span>Telegraph</td><td>A readable cue such as posture, movement or sound that may help interpret an action; it does not guarantee the outcome or prescribe a response.</td></tr><tr><td><span id="consistency"></span>Consistency</td><td>Repeatability of execution or results; distinct from the chance to hit, and not a guarantee of success.</td></tr><tr><td><span id="handling"></span>Handling</td><td>How an item or action manages control, stamina cost and recovery within its role; not simply extra damage.</td></tr><tr><td><span id="stamina"></span><a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Stamina</a></td><td>Physical resource that proposed martial actions compete for; exact costs and maximum-resource rules remain unsettled.</td></tr><tr><td><span id="fatigue"></span>Fatigue</td><td>Exertion pressure that may affect sustained activity; whether it is derived from stamina or represented separately remains unresolved.</td></tr><tr><td><span id="counter"></span>Counter</td><td>A response suited to an opposing action or situation; timing, eligibility and matchups matter, so a response is not a guaranteed hit.</td></tr><tr><td><span id="brace"></span><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Brace</a></td><td>A proposed committed defensive response against compatible attacks; feints, delays or flanks may defeat it, and a wasted attempt still costs time and stamina.</td></tr><tr><td><span id="riposte"></span><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Riposte</a></td><td>A candidate defensive response with timing, resource and matchup requirements; its exact behavior is not finalized.</td></tr></tbody></table><h2 id="what-s-new-in-syrolands" tabindex="-1">What&#39;s new in Syrolands <a class="header-anchor" href="#what-s-new-in-syrolands" aria-label="Permalink to &quot;What&#39;s new in Syrolands&quot;">​</a></h2><p>These terms connect character capability, player decisions and learned knowledge across systems. Some names are familiar from UO, but Syrolands definitions govern this guide; Mastery does not automatically mean UO&#39;s later Skill Masteries system.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You learn a Technique, improve its Familiarity through practice and choose it for your Prepared Repertoire. Your Skill still matters when you attempt it; having it ready does not guarantee a hit.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/introduction.html">Introduction</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Spell Memory</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/">Design Specs: all systems and detailed definitions</a></p>',14)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
